import sys
import heapq

d = sys.stdin.read().split()
n, m, w = int(d[0]), int(d[1]), int(d[2])
g = [[int(d[3 + i * m + j]) for j in range(m)] for i in range(n)]
caves = [(i, j) for i in range(n) for j in range(m) if g[i][j] > 0]
INF = float('inf')
dist = {(0, 0): 0}
h = [(0, 0, 0)]
while h:
    c, i, j = heapq.heappop(h)
    if dist.get((i, j), INF) < c:
        continue
    nxt = []
    for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
        if 0 <= ni < n and 0 <= nj < m and g[ni][nj] >= 0:
            nxt.append((c + w, ni, nj))
    if g[i][j] > 0:
        for (x, y) in caves:
            if (x, y) != (i, j):
                nxt.append((c + g[i][j] + g[x][y], x, y))
    for nc, ni, nj in nxt:
        if nc < dist.get((ni, nj), INF):
            dist[(ni, nj)] = nc
            heapq.heappush(h, (nc, ni, nj))
print(dist.get((n - 1, m - 1), -1))

